INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20QRZIF', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A warehouse can hold at most $800$ kilograms of cargo. Each large crate weighs $37$ kilograms and each small crate weighs $11$ kilograms. The warehouse operator must store at least $9$ small crates. If $L$ represents the number of large crates and $S$ represents the number of small crates, which system of inequalities best models these constraints?', NULL, $lyceon_json$[{"key":"A","text":"$37L + 11S \\leq 800$, $S \\geq 9$, $L \\geq 0$"},{"key":"B","text":"$37L + 11S < 800$, $S > 9$, $L > 0$"},{"key":"C","text":"$11L + 37S \\leq 800$, $S \\geq 9$, $L \\geq 0$"},{"key":"D","text":"$37L + 11S \\geq 800$, $S \\leq 9$, $L \\geq 0$"}]$lyceon_json$::jsonb, 'A', NULL, E'Large crates weigh $37$ kg each and small crates weigh $11$ kg each, so the total weight is $37L + 11S$, which must be at most $800$ kg: $37L + 11S \\leq 800$. At least $9$ small crates means $S \\geq 9$, and the number of large crates cannot be negative: $L \\geq 0$. The distractor using strict inequalities ($<$ and $>$) misrepresents ''at most'' and ''at least,'' which include the boundary values. The distractor $11L + 37S \\leq 800$ swaps the weights of the two crate types. The distractor $37L + 11S \\geq 800$ reverses the weight constraint and the small-crate requirement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20R4F3D', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ that satisfies $\\sqrt{3x + 7} = 8$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{3}$"},{"key":"B","text":"$19$"},{"key":"C","text":"$\\frac{57}{2}$"},{"key":"D","text":"$57$"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides: $3x + 7 = 64$. Subtracting $7$: $3x = 57$. Dividing by $3$: $x = 19$. The distractor $\\frac{1}{3}$ results from forgetting to square the right side and solving $3x + 7 = 8$, giving $3x = 1$. The distractor $\\frac{57}{2}$ comes from dividing $57$ by $2$ instead of $3$, an arithmetic slip. The distractor $57$ results from stopping at $3x = 57$ without completing the final division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20RCULR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 + 13x - 48 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Factoring the quadratic: $x^2 + 13x - 48 = (x + 16)(x - 3) = 0$. Setting each factor equal to zero gives $x = -16$ or $x = 3$. Since $x > 0$, the answer is $x = 3$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2386BM9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A salesperson earns a base salary of $\\$2{,}700$ per month plus a commission of $4.5\\%$ on all sales exceeding $\\$15{,}000$ in a given month. In March, the salesperson earned a total of $\\$4{,}185$. What was the total amount of sales, in dollars, the salesperson made in March?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '48000', ARRAY['48000'], E'The commission earned is $\\$4{,}185 - \\$2{,}700 = \\$1{,}485$. This commission is $4.5\\%$ of the sales exceeding $\\$15{,}000$. Let $s$ represent total sales. Then $0.045(s - 15{,}000) = 1{,}485$. Dividing both sides by $0.045$ gives $s - 15{,}000 = 33{,}000$. Therefore $s = 48{,}000$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23H9UJ1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A polling organization surveys a random sample of 600 registered voters in a city and finds that $54\\%$ support a proposed park expansion. The margin of error for the survey is $4$ percentage points. Which of the following is the most appropriate conclusion based on these results?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $54\\%$ of all registered voters in the city support the park expansion."},{"key":"B","text":"Between $50\\%$ and $58\\%$ of the 600 voters surveyed support the park expansion."},{"key":"C","text":"At least $50\\%$ of all registered voters in the city definitely support the park expansion."},{"key":"D","text":"It is plausible that between $50\\%$ and $58\\%$ of all registered voters in the city support the park expansion."}]$lyceon_json$::jsonb, 'D', NULL, E'The margin of error creates a confidence interval around the sample statistic: $54\\% \\pm 4\\%$, or $50\\%$ to $58\\%$. This interval applies to the population parameter (all registered voters), not the sample. It is plausible that the true proportion falls within this range. The claim that exactly $54\\%$ of all voters support the expansion treats the sample statistic as the exact population parameter. The claim about the 600 surveyed voters misapplies the margin of error to the sample rather than the population. The claim that at least $50\\%$ definitely support the expansion overstates the certainty of the interval — the margin of error expresses plausibility, not a guarantee.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23WY19V', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{8x^3 - 27}{4x^2 + 6x + 9}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 3$"},{"key":"B","text":"$8x - 27$"},{"key":"C","text":"$2x - 3$"},{"key":"D","text":"$2x^2 - 3$"}]$lyceon_json$::jsonb, 'C', NULL, E'The numerator is a difference of cubes: $8x^3 - 27 = (2x)^3 - 3^3 = (2x - 3)(4x^2 + 6x + 9)$. Dividing by $(4x^2 + 6x + 9)$ gives $2x - 3$. The distractor $2x + 3$ applies the wrong sign, as though the factorization were a sum of cubes. The distractor $8x - 27$ results from dividing only the cube terms by $x^2$ and by a constant without using the difference-of-cubes identity. The distractor $2x^2 - 3$ incorrectly retains a squared term, confusing the cube root of $8x^3$ with a partial factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM241VKNF', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $p$ does the system of equations $px + 6y = 21$ and $4x - 3y = 7$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$2$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system of two linear equations has no solution when the lines are parallel: equal slopes but different intercepts. Writing both equations in slope-intercept form, the first gives $y = -\\frac{p}{6}x + \\frac{21}{6}$ and the second gives $y = \\frac{4}{3}x - \\frac{7}{3}$. Setting the slopes equal: $-\\frac{p}{6} = \\frac{4}{3}$, so $p = -8$. The intercepts $\\frac{21}{6} = 3.5$ and $-\\frac{7}{3} \\approx -2.33$ are different, confirming no solution. The value $-2$ results from incomplete reasoning about the ratio of coefficients. The value 2 comes from a sign error when cross-multiplying. The value 8 results from dropping the negative sign in the slope comparison.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2478CTQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In a triangle, two of the interior angles measure $71°$ and $52°$. What is the measure, in degrees, of an exterior angle formed at the vertex of the third interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$123$"},{"key":"B","text":"$57$"},{"key":"C","text":"$109$"},{"key":"D","text":"$237$"}]$lyceon_json$::jsonb, 'A', NULL, E'The third interior angle measures $180° - 71° - 52° = 57°$. The exterior angle at that vertex is supplementary to the interior angle: $180° - 57° = 123°$. Equivalently, the exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $71° + 52° = 123°$. The value $57°$ is the third interior angle, not the exterior angle. The value $109°$ equals $180° - 71°$, the supplement of the wrong interior angle. The value $237°$ equals $360° - 123°$, confusing the exterior angle with the reflex angle.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25FVGKG', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = mx + 11$, where $m$ is a constant. The point $(k,\\, 3k - 5)$ lies on the line $y = g(x)$. If $g(7) = 39$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-16$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$8$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'A', NULL, E'From $g(7) = 39$: $7m + 11 = 39$, so $7m = 28$ and $m = 4$. The function is $g(x) = 4x + 11$. Since the graph passes through $(k, 3k - 5)$, we have $g(k) = 3k - 5$, giving $4k + 11 = 3k - 5$. Subtracting $3k$ from both sides yields $k + 11 = -5$, so $k = -16$. The value $-8$ comes from incorrectly computing $m = 2$ by halving. The value 8 results from a sign error when solving $k + 11 = -5$. The value 16 results from dropping the negative sign entirely in the final step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25SHVYR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid is formed by removing a cone from the interior of a cylinder. Both the cone and the cylinder have a radius of 4 and a height of 9, and the base of the cone coincides with one base of the cylinder. What is the volume of the remaining solid?', NULL, $lyceon_json$[{"key":"A","text":"$48\\pi$"},{"key":"B","text":"$72\\pi$"},{"key":"C","text":"$96\\pi$"},{"key":"D","text":"$144\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of the cylinder is $\\pi r^2 h = \\pi(4)^2(9) = 144\\pi$. The volume of the cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}(144\\pi) = 48\\pi$. The remaining solid has volume $144\\pi - 48\\pi = 96\\pi$. The value $48\\pi$ is only the cone''s volume, not the remaining solid. The value $72\\pi$ results from subtracting half of the cylinder''s volume instead of one-third. The value $144\\pi$ is the full cylinder without removing the cone.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM262CXCH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangle has a base of 23 inches and a height of 14 inches. What is the area, in square inches, of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$322$"},{"key":"B","text":"$161$"},{"key":"C","text":"$74$"},{"key":"D","text":"$37$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2}(23)(14) = 161$ square inches. The value $322$ results from multiplying base by height without the $\\frac{1}{2}$ factor. The value $74$ comes from incorrectly doubling the sum of base and height. The value $37$ comes from adding base and height ($23 + 14$) rather than using the area formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27XQ490', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A water tank drains at a constant rate. At time $t = 4$ minutes, the tank holds 137 gallons, and at $t = 11$ minutes, it holds 74 gallons. At what time, in minutes, will the tank hold exactly 20 gallons?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$17$"},{"key":"C","text":"$18$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate of change is $\\frac{74 - 137}{11 - 4} = \\frac{-63}{7} = -9$ gallons per minute. Using the point $(4, 137)$, the function is $f(t) = -9(t - 4) + 137 = -9t + 173$. Setting $f(t) = 20$ gives $-9t + 173 = 20$, so $9t = 153$ and $t = 17$. The value 15 results from an arithmetic slip in the final division. The value 18 comes from using a slightly incorrect rate or rounding during intermediate steps. The value 20 results from confusing the target volume with the time variable.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29KJYIS', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $9(2x - 7) - 4(3x + 5)$?', NULL, $lyceon_json$[{"key":"A","text":"$6x - 43$"},{"key":"B","text":"$30x - 83$"},{"key":"C","text":"$6x - 83$"},{"key":"D","text":"$30x - 43$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing gives $9(2x - 7) = 18x - 63$ and $-4(3x + 5) = -12x - 20$. Combining: $18x - 12x = 6x$ and $-63 - 20 = -83$, so the expression simplifies to $6x - 83$. The distractor $6x - 43$ results from treating $-4(5)$ as $+20$ instead of $-20$, a sign error. The distractor $30x - 83$ results from adding $18x + 12x$ instead of subtracting. The distractor $30x - 43$ combines both errors.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AD2YJQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $5x^2 - 14x + 11 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-14)^2 - 4(5)(11) = 196 - 220 = -24$. Since the discriminant is negative, the equation has $0$ real solutions. The distractor $1$ confuses a negative discriminant with a zero discriminant, which would give exactly one repeated root. The distractor $2$ assumes every quadratic equation has two real solutions regardless of the discriminant. The distractor $4$ incorrectly doubles the degree or misapplies the relationship between the equation and its number of solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BLH14G', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x - 2y = 18$. Line $q$ is perpendicular to line $p$ and passes through the point where line $p$ intersects the $y$-axis. What is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5y = -45$"},{"key":"B","text":"$2x - 5y = 45$"},{"key":"C","text":"$5x + 2y = -18$"},{"key":"D","text":"$2x + 5y = 45$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept of line $p$ is found by setting $x = 0$: $-2y = 18$, so $y = -9$. The point is $(0, -9)$. The slope of line $p$ is $\\frac{5}{2}$, so the perpendicular slope is $-\\frac{2}{5}$. Line $q$: $y - (-9) = -\\frac{2}{5}(x - 0)$, giving $y = -\\frac{2}{5}x - 9$. Multiplying by $5$: $5y = -2x - 45$, or $2x + 5y = -45$. The distractor $2x - 5y = 45$ has slope $\\frac{2}{5}$ (positive instead of negative), omitting the sign change in the negative reciprocal. The distractor $5x + 2y = -18$ uses the original coefficients negated rather than the reciprocal, yielding slope $-\\frac{5}{2}$ instead of $-\\frac{2}{5}$. The distractor $2x + 5y = 45$ has the correct slope but the wrong constant, as if the $y$-intercept were $+9$ instead of $-9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DX4EK3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher wants to determine whether a new vitamin supplement improves memory in adults over 50. The researcher recruits 150 volunteers over the age of 50 and randomly assigns 75 of them to take the supplement daily for 6 months while the other 75 take a placebo. At the end of 6 months, the supplement group performs significantly better on a standardized memory test. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The supplement causes improved memory in all adults."},{"key":"B","text":"Taking the supplement likely caused the improved memory test scores, but the results cannot necessarily be generalized to all adults over 50."},{"key":"C","text":"There is an association between the supplement and improved memory, but a cause-and-effect relationship cannot be established."},{"key":"D","text":"The results can be generalized to all adults over 50 in the population because the study used random assignment."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researcher used random assignment to treatment and control groups, a cause-and-effect conclusion is supported — the supplement likely caused the improvement. However, the participants were volunteers, not a random sample from the population of all adults over 50, so the results cannot necessarily be generalized beyond similar volunteers. The claim that the supplement causes improved memory in all adults overgeneralizes both the age group and the population. The claim that causation cannot be established fails to recognize that random assignment to groups allows causal inference. The claim that results generalize to all adults over 50 confuses random assignment (which supports causation) with random sampling (which supports generalization).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E9L7LZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $p$ is defined by $p(x) = \\frac{x^2 - 17x + 30}{x - 2}$ for $x \\neq 2$. It can be shown that $p(x) = x - c$ for some constant $c$. What is the value of $c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'To simplify $p(x) = \\frac{x^2 - 17x + 30}{x - 2}$, factor the numerator. We need two numbers that multiply to $30$ and add to $-17$: those are $-2$ and $-15$. So $x^2 - 17x + 30 = (x - 2)(x - 15)$. Dividing by $(x - 2)$ gives $p(x) = x - 15$ for $x \\neq 2$. Comparing with $p(x) = x - c$, we find $c = 15$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EZVLK3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line passes through the points $(2, 5)$ and $(6, 13)$. What is the slope of the line?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{2}$"},{"key":"B","text":"$2$"},{"key":"C","text":"$4$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{13 - 5}{6 - 2} = \\frac{8}{4} = 2$. The value $\\frac{1}{2}$ results from inverting the slope formula, computing $\\frac{6 - 2}{13 - 5}$ instead. The value $4$ comes from using only the denominator of the slope fraction (the change in $x$). The value $8$ comes from computing only the numerator (the change in $y$) without dividing by the change in $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HAV76G', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In a right triangle, $\\sin \\theta = \\frac{3}{5}$ for one of the acute angles $\\theta$. The hypotenuse of this triangle has length 35. What is the perimeter of the triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '84', ARRAY['84'], E'Since $\\sin \\theta = \\frac{3}{5}$, the sides of the right triangle are in the ratio $3:4:5$ (opposite to $\\theta$, adjacent to $\\theta$, hypotenuse). With a hypotenuse of $35$, the scale factor is $\\frac{35}{5} = 7$. The three sides are $3 \\times 7 = 21$, $4 \\times 7 = 28$, and $35$. The perimeter is $21 + 28 + 35 = 84$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I0LIVD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If the equation $4x^2 - 28x + k = 0$ has exactly one real solution, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '49', ARRAY['49'], E'A quadratic equation has exactly one real solution when its discriminant equals zero. For $4x^2 - 28x + k = 0$, the discriminant is $(-28)^2 - 4(4)(k) = 784 - 16k$. Setting this equal to zero: $784 - 16k = 0$, so $16k = 784$, giving $k = 49$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IF9FQE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $x \\neq -5$ and $x \\neq 2$, which of the following is equivalent to $\\frac{3}{x + 5} - \\frac{1}{x - 2}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2x - 11}{x^2 + 3x - 10}$"},{"key":"B","text":"$\\frac{2x - 1}{x^2 + 3x - 10}$"},{"key":"C","text":"$\\frac{4x - 11}{x^2 + 3x - 10}$"},{"key":"D","text":"$\\frac{2}{x^2 + 3x - 10}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The common denominator is $(x + 5)(x - 2) = x^2 + 3x - 10$. Rewriting: $\\frac{3(x - 2) - 1(x + 5)}{x^2 + 3x - 10} = \\frac{3x - 6 - x - 5}{x^2 + 3x - 10} = \\frac{2x - 11}{x^2 + 3x - 10}$. The distractor $\\frac{2x - 1}{x^2 + 3x - 10}$ results from computing $-6 - (-5) = -1$ instead of $-6 - 5 = -11$, a sign error in distributing the subtraction. The distractor $\\frac{4x - 11}{x^2 + 3x - 10}$ results from adding $3x + x$ instead of $3x - x$ for the numerator coefficient. The distractor $\\frac{2}{x^2 + 3x - 10}$ results from subtracting only the numerator constants $3 - 1 = 2$ without properly computing the cross-multiplied numerator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IQUICO', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'If $3x + 2y = 19$ and $x - 4y = -3$, what is the value of $x + y$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$9$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'From the second equation, $x = 4y - 3$. Substituting into the first equation gives $3(4y - 3) + 2y = 19$, which simplifies to $12y - 9 + 2y = 19$, so $14y = 28$ and $y = 2$. Then $x = 4(2) - 3 = 5$. Therefore $x + y = 5 + 2 = 7$. The value 5 comes from reporting only the value of $x$ without adding $y$. The value 9 results from an arithmetic error when substituting back. The value 11 comes from incorrectly setting up the substitution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IR4DXN', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation of a line is $3x + 7y = 42$. A second line is parallel to this line and passes through the point $(2, -1)$. Which of the following is the equation of the second line?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 7y = -1$"},{"key":"B","text":"$7x - 3y = 17$"},{"key":"C","text":"$3x + 7y = 42$"},{"key":"D","text":"$3x - 7y = 13$"}]$lyceon_json$::jsonb, 'A', NULL, E'Parallel lines have the same slope, so the second line has the form $3x + 7y = c$. Substituting the point $(2, -1)$: $3(2) + 7(-1) = 6 - 7 = -1$, so the equation is $3x + 7y = -1$. The distractor $7x - 3y = 17$ uses a perpendicular slope (swapping and negating coefficients) rather than the same slope. The distractor $3x + 7y = 42$ is the original line itself, not the parallel line through $(2, -1)$. The distractor $3x - 7y = 13$ changes the sign of the $y$-coefficient, producing a line with a different slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J191MN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collected data on the number of hours spent studying and the corresponding test scores for a group of students. The line of best fit for the data is $y = 7.3x + 41$, where $x$ is the number of hours studied and $y$ is the predicted test score. Which of the following is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour studied, the predicted test score increases by $41$ points."},{"key":"B","text":"A student who does not study at all is predicted to score $7.3$ on the test."},{"key":"C","text":"For each additional hour studied, the predicted test score increases by $7.3$ points."},{"key":"D","text":"A student who studies for $1$ hour is predicted to score $48.3$ on the test."}]$lyceon_json$::jsonb, 'C', NULL, E'In the equation $y = 7.3x + 41$, the slope is $7.3$, which means that for each additional hour studied, the predicted test score increases by $7.3$ points. The claim that the score increases by $41$ points per hour incorrectly identifies the $y$-intercept as the slope. The claim that a student who does not study scores $7.3$ swaps the roles of the slope and $y$-intercept. The statement that a student studying $1$ hour scores $48.3$ computes a specific prediction ($7.3(1) + 41 = 48.3$) rather than interpreting what the slope represents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JEXYS0', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which ordered pair $(x, y)$ is a solution to the system of inequalities below? $$y \\leq 3x - 5$$ $$y > -2x + 7$$', NULL, $lyceon_json$[{"key":"A","text":"$(1, 3)$"},{"key":"B","text":"$(3, 1)$"},{"key":"C","text":"$(4, 2)$"},{"key":"D","text":"$(2, 5)$"}]$lyceon_json$::jsonb, 'C', NULL, E'For $(4, 2)$: the first inequality gives $2 \\leq 3(4) - 5 = 7$, which is true, and the second gives $2 > -2(4) + 7 = -1$, which is also true. For $(1, 3)$: $3 \\leq 3(1) - 5 = -2$ is false. For $(3, 1)$: $1 \\leq 3(3) - 5 = 4$ is true, but $1 > -2(3) + 7 = 1$ is false because $1$ is not strictly greater than $1$. For $(2, 5)$: $5 \\leq 3(2) - 5 = 1$ is false.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JGZIFW', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $7x - 19 = 23$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$-6$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding 19 to both sides gives $7x = 42$. Dividing both sides by 7 gives $x = 6$. The value 4 results from dividing 42 by 7 incorrectly or subtracting instead of adding 19. The value $-6$ results from a sign error when isolating $x$. The value 8 results from an error in setting up or simplifying the equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JO9IO7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'For what value of $a$ does the equation $a(3x - 5) + 14 = 9x - a$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'C', NULL, E'Expanding the left side gives $3ax - 5a + 14 = 9x - a$. For no solution, the coefficients of $x$ must be equal while the constants differ. Setting $3a = 9$ gives $a = 3$. Substituting $a = 3$ into the constants: the left side gives $-5(3) + 14 = -1$ and the right side gives $-3$. Since $-1 \\neq -3$, the equation has no solution when $a = 3$. The value $-3$ results from a sign error when equating the coefficients. The value 1 comes from incomplete reasoning about the constant terms. The value 9 confuses the coefficient of $x$ on the right side with the required value of $a$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JU8L2U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A teacher recorded the number of books each of 21 students read over the summer. The results are summarized below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KMD9E6', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A function $f$ is defined by $f(x) = -3x + 17$. What is the value of $f(-4)$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$29$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$-29$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $-4$ for $x$ gives $f(-4) = -3(-4) + 17 = 12 + 17 = 29$. The value 5 results from computing $-3(4) + 17$ instead of $-3(-4) + 17$, dropping the negative on the input. The value $-5$ comes from computing $-3(4) - 17$, both dropping the negative input and subtracting instead of adding. The value $-29$ results from incorrectly computing $-12 - 17$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MP1KBH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one of the acute angles is $\\theta$ and $\\sin \\theta = \\frac{7}{25}$. What is the value of $\\cos \\theta$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{24}$"},{"key":"B","text":"$\\frac{18}{25}$"},{"key":"C","text":"$\\frac{24}{25}$"},{"key":"D","text":"$\\frac{25}{24}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin \\theta = \\frac{7}{25}$, the opposite side is $7$ and the hypotenuse is $25$. Using the Pythagorean theorem, the adjacent side is $\\sqrt{25^2 - 7^2} = \\sqrt{625 - 49} = \\sqrt{576} = 24$. Therefore $\\cos \\theta = \\frac{24}{25}$. The value $\\frac{7}{24}$ is $\\tan \\theta$, not $\\cos \\theta$. The value $\\frac{18}{25}$ results from subtracting $25 - 7 = 18$ instead of using the Pythagorean theorem. The value $\\frac{25}{24}$ is $\\sec \\theta$, the reciprocal of cosine.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MW2XMO', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'A theater sells adult tickets for $\\$11$ each and child tickets for $\\$7$ each. On one evening, 45 tickets were sold for a total of $\\$387$. How many adult tickets were sold?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'Let $a$ represent the number of adult tickets and $c$ the number of child tickets. The system is $a + c = 45$ and $11a + 7c = 387$. From the first equation, $c = 45 - a$. Substituting gives $11a + 7(45 - a) = 387$, which simplifies to $11a + 315 - 7a = 387$, so $4a = 72$ and $a = 18$. Therefore 18 adult tickets were sold.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MY8NQ7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle in the $xy$-plane passes through the points $(10, 8)$ and $(3, 7)$. The center of the circle lies on the line $y = -2x + 18$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{50}$"},{"key":"B","text":"$\\frac{\\sqrt{50}}{2}$"},{"key":"C","text":"$\\sqrt{65}$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'D', NULL, E'The center must be equidistant from $(10, 8)$ and $(3, 7)$, so it lies on the perpendicular bisector of the segment connecting them. The midpoint is $\\left(\\frac{13}{2}, \\frac{15}{2}\\right)$ and the slope of the segment is $\\frac{8 - 7}{10 - 3} = \\frac{1}{7}$, so the perpendicular bisector has slope $-7$. The bisector equation is $y - \\frac{15}{2} = -7\\left(x - \\frac{13}{2}\\right)$, which simplifies to $y = -7x + 53$. Setting this equal to the given line $y = -2x + 18$ yields $-7x + 53 = -2x + 18$, so $5x = 35$ and $x = 7$, giving $y = 4$. The center is $(7, 4)$. The radius is $\\sqrt{(10 - 7)^2 + (8 - 4)^2} = \\sqrt{9 + 16} = 5$. The value $\\sqrt{50}$ is the distance between the two given points (the chord length), not the radius. The value $\\frac{\\sqrt{50}}{2}$ incorrectly halves the chord as though it were a diameter. The value $\\sqrt{65}$ is the distance from the center $(7, 4)$ to the origin.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NE6FGS', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A printing company charges $\\$13$ per booklet plus a flat $\\$47$ shipping fee per order. A customer has at most $\\$150$ to spend on a single order. What is the maximum number of booklets the customer can include in the order?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The total cost for $n$ booklets is $13n + 47$. Setting up the inequality $13n + 47 \\leq 150$ and subtracting $47$ from both sides gives $13n \\leq 103$. Dividing both sides by $13$ yields $n \\leq 7.923\\ldots$, so the maximum whole number of booklets is $7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NWWZGP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $g$ is defined by $g(x) = 47 \\cdot \\left(\\frac{1}{3}\\right)^x$. What is the value of $g(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '47', ARRAY['47'], E'Substituting $x = 0$ gives $g(0) = 47 \\cdot \\left(\\frac{1}{3}\\right)^0$. Since any nonzero base raised to the power of $0$ equals $1$, this simplifies to $g(0) = 47 \\cdot 1 = 47$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OA0CZ4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A recipe requires 13 ounces of butter for every 3 batches of scones. How many ounces of butter are needed to make 9 batches of scones?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '39', ARRAY['39'], E'Since 13 ounces of butter are needed for every 3 batches, the unit rate is $\\frac{13}{3}$ ounces per batch. For 9 batches, the amount of butter needed is $\\frac{13}{3} \\times 9 = 39$ ounces. Equivalently, 9 batches is 3 times as many as 3 batches, so the butter required is $13 \\times 3 = 39$ ounces.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OQ1N55', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{4x^2 + 20x + 25}{2x + 5}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x - 5$"},{"key":"B","text":"$4x + 5$"},{"key":"C","text":"$2x^2 + 10x + 5$"},{"key":"D","text":"$2x + 5$"}]$lyceon_json$::jsonb, 'D', NULL, E'The numerator $4x^2 + 20x + 25$ is a perfect square trinomial: $(2x + 5)^2$. Dividing by $(2x + 5)$ gives $\\frac{(2x + 5)^2}{2x + 5} = 2x + 5$. The distractor $2x - 5$ results from factoring as $(2x + 5)(2x - 5)$ instead of $(2x + 5)^2$, confusing the perfect square with a difference of squares. The distractor $4x + 5$ incorrectly divides only the leading coefficient by 2. The distractor $2x^2 + 10x + 5$ results from dividing each term individually by 2 rather than by the binomial $(2x + 5)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q0Z95J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $53°$. What is the measure, in degrees, of the co-interior angle (same-side interior angle) on the same side of the transversal?', NULL, $lyceon_json$[{"key":"A","text":"$37$"},{"key":"B","text":"$53$"},{"key":"C","text":"$127$"},{"key":"D","text":"$137$"}]$lyceon_json$::jsonb, 'C', NULL, E'Co-interior angles (same-side interior angles) formed by parallel lines and a transversal are supplementary, meaning they sum to $180°$. Therefore the co-interior angle measures $180° - 53° = 127°$. The value $37°$ incorrectly applies the complementary angle relationship ($90° - 53°$). The value $53°$ confuses the co-interior angle with the alternate interior angle, which would be congruent. The value $137°$ is an arithmetic error in the subtraction from $180°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QC8HWQ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which inequality represents all values of $x$ that satisfy $7x - 19 > 23$?', NULL, $lyceon_json$[{"key":"A","text":"$x > 6$"},{"key":"B","text":"$x > 3$"},{"key":"C","text":"$x < 6$"},{"key":"D","text":"$x > -6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $19$ to both sides gives $7x > 42$, and dividing both sides by $7$ gives $x > 6$. The distractor $x > 3$ results from dividing $42$ by $14$ instead of $7$. The distractor $x < 6$ incorrectly reverses the inequality direction when dividing by a positive number. The distractor $x > -6$ introduces an incorrect sign change on the result.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QD5JEW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $(3x + 11)(3x - 11) - (3x + 2)^2$?', NULL, $lyceon_json$[{"key":"A","text":"$-12x - 117$"},{"key":"B","text":"$-12x - 125$"},{"key":"C","text":"$12x - 125$"},{"key":"D","text":"$-125$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the difference of squares: $(3x + 11)(3x - 11) = 9x^2 - 121$. Expanding the perfect square: $(3x + 2)^2 = 9x^2 + 12x + 4$. Subtracting: $(9x^2 - 121) - (9x^2 + 12x + 4) = -12x - 125$. The distractor $-12x - 117$ comes from computing $-121 + 4 = -117$ instead of $-121 - 4 = -125$, a sign error when distributing the negative. The distractor $12x - 125$ has the correct constant but an incorrect positive coefficient on $x$. The distractor $-125$ omits the $-12x$ term entirely, as though the $9x^2$ terms canceling also eliminates the linear term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QI90GS', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'grid_in', E'If $\\frac{14p^9}{2p^3} = ap^b$ for all positive values of $p$, where $a$ and $b$ are constants, what is the value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Dividing the coefficients gives $\\frac{14}{2} = 7$. Applying the quotient rule for exponents: $\\frac{p^9}{p^3} = p^{9-3} = p^6$. Therefore $\\frac{14p^9}{2p^3} = 7p^6$, so $a = 7$ and $b = 6$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QSIPM2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = a \\cdot b^x + k$, where $a$, $b$, and $k$ are constants. The function $f$ has a horizontal asymptote at $y = -5$ and passes through the points $(0, 19)$ and $(1, 43)$. What is the value of $a + b + k$?', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$21$"},{"key":"C","text":"$26$"},{"key":"D","text":"$31$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $21$. For $f(x) = a \\cdot b^x + k$, the horizontal asymptote is $y = k$, so $k = -5$. Using the point $(0, 19)$: $a \\cdot b^0 + (-5) = 19$, which gives $a - 5 = 19$, so $a = 24$. Using the point $(1, 43)$: $24b + (-5) = 43$, which gives $24b = 48$, so $b = 2$. Therefore $a + b + k = 24 + 2 + (-5) = 21$. The value $19$ comes from simply restating $f(0)$ without computing the constants. The value $26$ results from computing $a + b = 24 + 2$ but omitting $k$. The value $31$ arises from a sign error on the asymptote, using $k = +5$ instead of $-5$ in the final sum: $24 + 2 + 5 = 31$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QW5JQ5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $y = x - 2$ and $x^2 + y^2 = 34$, what is the value of $y$ when $y > 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$3$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $y = x - 2$ into $x^2 + y^2 = 34$: $x^2 + (x - 2)^2 = 34$, which expands to $x^2 + x^2 - 4x + 4 = 34$, or $2x^2 - 4x - 30 = 0$. Dividing by $2$: $x^2 - 2x - 15 = 0$, which factors as $(x - 5)(x + 3) = 0$. So $x = 5$ or $x = -3$. Using $y = x - 2$: when $x = 5$, $y = 3$; when $x = -3$, $y = -5$. Since $y > 0$, the answer is $3$. The distractor $-5$ is the negative $y$-value from the other solution pair. The distractor $-3$ is the negative $x$-value, not the corresponding $y$. The distractor $5$ is the $x$-value of the solution where $y > 0$, not the $y$-value itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RP5LO1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $h$ is defined by $h(x) = x^3 - 6x + 2$. What is the value of $h(-1)$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $7$. Substituting $x = -1$ gives $h(-1) = (-1)^3 - 6(-1) + 2 = -1 + 6 + 2 = 7$. The value $-5$ results from a sign error, treating $-6(-1)$ as $-6$ instead of $+6$, yielding $-1 - 6 + 2 = -5$. The value $-3$ comes from an arithmetic slip in the final addition. The value $3$ results from computing $(-1)^3$ as $+1$ instead of $-1$, giving $1 + 0 + 2 = 3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
