INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S7CEIT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'For the function $g$, the values $g(0) = 4$, $g(1) = 12$, $g(2) = 36$, and $g(3) = 108$ are known. Which of the following equations could define $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$g(x) = 8x + 4$"},{"key":"B","text":"$g(x) = 4x^2 + 4x + 4$"},{"key":"C","text":"$g(x) = 3 \\cdot 4^x$"},{"key":"D","text":"$g(x) = 4 \\cdot 3^x$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $g(x) = 4 \\cdot 3^x$. Checking: $g(0) = 4 \\cdot 3^0 = 4$, $g(1) = 4 \\cdot 3^1 = 12$, $g(2) = 4 \\cdot 3^2 = 36$, and $g(3) = 4 \\cdot 3^3 = 108$, which matches all values in the table. The linear equation $8x + 4$ gives $g(0) = 4$ and $g(1) = 12$ but $g(2) = 20 \\neq 36$, failing at the third value. The quadratic $4x^2 + 4x + 4$ gives $g(0) = 4$ and $g(1) = 12$ but $g(2) = 28 \\neq 36$. The expression $3 \\cdot 4^x$ swaps the initial value and base, giving $g(0) = 3 \\neq 4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SBGY2L', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 2(x - 7)^2 - 19$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-19$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$7$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-19$. The function is in vertex form $f(x) = a(x - h)^2 + k$ with $a = 2 > 0$, so the parabola opens upward and has a minimum at the vertex. The vertex is at $(7, -19)$, so the minimum value of $f(x)$ is $-19$. The value $7$ is the $x$-coordinate of the vertex, not the minimum output value. The values $-7$ and $19$ each arise from sign errors when reading the vertex form parameters.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SHO3FY', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $f$ satisfies $f(2) = 13$, $f(5) = 28$, and $f(8) = 43$. What is the value of $f(14)$?', NULL, $lyceon_json$[{"key":"A","text":"$58$"},{"key":"B","text":"$63$"},{"key":"C","text":"$73$"},{"key":"D","text":"$78$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate of change is $\\frac{28 - 13}{5 - 2} = \\frac{15}{3} = 5$. Using the point $(2, 13)$: $f(x) = 5(x - 2) + 13 = 5x + 3$. Evaluating at $x = 14$ gives $f(14) = 5(14) + 3 = 73$. The value 58 results from computing $f(11)$ instead of $f(14)$ or adding one fewer interval. The value 63 comes from an arithmetic slip in the final calculation. The value 78 results from using an incorrect $y$-intercept of 8 instead of 3.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TC2ZNI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $p$ is defined by $p(x) = -x^2 + 18x - 53$. For what value of $x$ does $p(x)$ attain its maximum value?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Since the coefficient of $x^2$ is negative ($a = -1$), the parabola opens downward and has a maximum at its vertex. The $x$-coordinate of the vertex is $x = -\\frac{b}{2a} = -\\frac{18}{2(-1)} = -\\frac{18}{-2} = 9$. Therefore $p(x)$ attains its maximum value at $x = 9$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TMTZ8B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has the equation $(x + 3)^2 + (y - 8)^2 = 169$. What is the area of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$26\\pi$"},{"key":"B","text":"$169\\pi$"},{"key":"C","text":"$338\\pi$"},{"key":"D","text":"$13\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The equation $(x + 3)^2 + (y - 8)^2 = 169$ is in standard form $(x - h)^2 + (y - k)^2 = r^2$, so $r^2 = 169$ and $r = 13$. The area is $\\pi r^2 = 169\\pi$. The value $26\\pi$ equals $2\\pi r$, which is the circumference, not the area. The value $338\\pi$ doubles the correct area without justification. The value $13\\pi$ incorrectly computes $\\pi r$ instead of $\\pi r^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U3M8W5', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the system of equations $2x + y = 17$ and $x - y = 4$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$9$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates $y$: $(2x + y) + (x - y) = 17 + 4$, which gives $3x = 21$ and $x = 7$. The value 5 results from solving for $y$ instead and reporting that value. The value 9 comes from setting up the elimination incorrectly, such as subtracting the equations instead of adding. The value 3 results from an arithmetic slip in the final division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U7E2P1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What are all the solutions to $\\sqrt{3x + 7} = x - 1$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -1$ only"},{"key":"B","text":"$x = 6$ only"},{"key":"C","text":"$x = -1$ and $x = 6$"},{"key":"D","text":"$x = 1$ and $x = -6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides: $3x + 7 = (x - 1)^2 = x^2 - 2x + 1$. Rearranging: $x^2 - 5x - 6 = 0$, which factors as $(x - 6)(x + 1) = 0$, giving $x = 6$ or $x = -1$. Checking $x = 6$: $\\sqrt{3(6) + 7} = \\sqrt{25} = 5$ and $6 - 1 = 5$, which is valid. Checking $x = -1$: $\\sqrt{3(-1) + 7} = \\sqrt{4} = 2$ and $-1 - 1 = -2$, so $2 \\neq -2$, which means $x = -1$ is extraneous. The only solution is $x = 6$. The distractor $x = -1$ only selects the extraneous solution. The distractor $x = -1$ and $x = 6$ fails to check for extraneous solutions. The distractor $x = 1$ and $x = -6$ reverses the signs of both algebraic solutions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UCVWK5', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'If the expression $\\frac{49t^2 - 81}{7t + 9}$ can be written in the form $at + b$, where $a$ and $b$ are constants, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-2', ARRAY['-2'], E'The numerator is a difference of squares: $49t^2 - 81 = (7t)^2 - 9^2 = (7t + 9)(7t - 9)$. Dividing by $(7t + 9)$ yields $7t - 9$. Therefore $a = 7$ and $b = -9$, so $a + b = 7 + (-9) = -2$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UPCXC8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store offers a $20\\%$ discount on a pair of shoes originally priced at $\\$85$. After the discount is applied, a $6\\%$ sales tax is added to the discounted price. What is the total cost of the shoes, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$68.00$"},{"key":"B","text":"$\\$72.08$"},{"key":"C","text":"$\\$73.10$"},{"key":"D","text":"$\\$90.10$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discounted price is $85 \\times 0.80 = \\$68.00$. Applying $6\\%$ sales tax to the discounted price gives $68 \\times 1.06 = \\$72.08$. The value $\\$68.00$ reflects only the discount without adding tax. The value $\\$73.10$ results from incorrectly computing tax on the original price ($85 \\times 0.06 = \\$5.10$) and adding it to the discounted price ($68 + 5.10 = 73.10$). The value $\\$90.10$ results from applying the $6\\%$ tax to the original price and stopping there ($85 \\times 1.06 = 90.10$), ignoring the discount entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WLUB4R', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ in the equation $\\frac{4(x - 3)}{5} + 2 = \\frac{x + 7}{5}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Multiplying both sides by 5 gives $4(x - 3) + 10 = x + 7$. Distributing gives $4x - 12 + 10 = x + 7$, which simplifies to $4x - 2 = x + 7$. Subtracting $x$ from both sides gives $3x - 2 = 7$. Adding 2 to both sides gives $3x = 9$, so $x = 3$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XY5NJM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'Which of the following is a value of $k$ for which the system of equations $y = 3x^2 + kx + 5$ and $y = 11x - 7$ has exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$5$"},{"key":"C","text":"$12$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $3x^2 + kx + 5 = 11x - 7$, which simplifies to $3x^2 + (k - 11)x + 12 = 0$. For exactly one real solution, the discriminant must equal zero: $(k - 11)^2 - 4(3)(12) = 0$, so $(k - 11)^2 = 144$. Taking square roots: $k - 11 = \\pm 12$, giving $k = 23$ or $k = -1$. Since $-1$ appears among the choices, the answer is $-1$. The distractor $5$ confuses the constant in the quadratic with the answer. The distractor $12$ takes $\\sqrt{144} = 12$ but does not add or subtract it from $11$. The distractor $22$ computes $11 + 11 = 22$ instead of $11 - 12 = -1$ or $11 + 12 = 23$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y6Z7E9', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A mechanic charges a $\\$53$ diagnostic fee plus $\\$79$ per hour of labor. If a customer''s total bill was $\\$369$, how many hours of labor were performed?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$4.67$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total bill is modeled by $53 + 79h = 369$. Subtracting 53 from both sides gives $79h = 316$. Dividing both sides by 79 gives $h = 4$. The value 3 results from an arithmetic slip when dividing 316 by 79. The value 5 arises from incorrectly setting up the equation without the diagnostic fee. The value 4.67 comes from dividing the total 369 by 79 without first subtracting the diagnostic fee.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YNIMA8', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(3, 11)$ and $(7, 31)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4/5', ARRAY['4/5', '0.8', '.8'], E'The slope is $\\frac{31 - 11}{7 - 3} = \\frac{20}{4} = 5$. Using point-slope form with $(3, 11)$: $y - 11 = 5(x - 3)$, which simplifies to $y = 5x - 4$. Setting $y = 0$ gives $0 = 5x - 4$, so $x = \\frac{4}{5}$. The $x$-intercept is $\\frac{4}{5}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YSU931', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'A linear function increases by 7 for every increase of 1 in $x$, and $f(0) = -11$. What is $f(3)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Since $f$ is linear with slope 7 and $y$-intercept $-11$, the function is $f(x) = 7x - 11$. Evaluating at $x = 3$ gives $f(3) = 7(3) - 11 = 21 - 11 = 10$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z01VTS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylindrical storage tank has a diameter of 6 feet and a height of 11 feet. The volume of the tank can be written as $k\\pi$ cubic feet, where $k$ is a positive integer. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '99', ARRAY['99'], E'The volume of a cylinder is $V = \\pi r^2 h$. The diameter is 6 feet, so the radius is 3 feet. Substituting gives $V = \\pi(3)^2(11) = \\pi(9)(11) = 99\\pi$. Since $V = k\\pi$, the value of $k$ is $99$. A common error is using the diameter instead of the radius, which would give $\\pi(6)^2(11) = 396\\pi$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZTT8S1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A cyclist travels at a constant speed of 23 kilometers per hour. A jogger travels at a constant speed of 9 kilometers per hour. Both start from the same location at the same time and travel in the same direction along the same straight path. After how many hours will the cyclist be exactly 49 kilometers ahead of the jogger?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{49}{23}$"},{"key":"B","text":"$\\frac{7}{2}$"},{"key":"C","text":"$\\frac{49}{9}$"},{"key":"D","text":"$\\frac{49}{32}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The cyclist gains ground on the jogger at a rate of $23 - 9 = 14$ kilometers per hour. To be 49 kilometers ahead, the time required is $\\frac{49}{14} = \\frac{7}{2}$ hours. The option $\\frac{49}{23}$ incorrectly divides by only the cyclist''s speed, ignoring the jogger. The option $\\frac{49}{9}$ incorrectly uses only the jogger''s speed as if the cyclist were stationary. The option $\\frac{49}{32}$ incorrectly adds the two speeds instead of subtracting them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2197U2T', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to present the debate between Everett and his critics regarding what the absence of number terms in Piraha signifies. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22BENET', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Marcia Chatelain has argued that fast-food franchises played a paradoxical role in Black economic life during the 1970s. On one hand, franchise ownership represented one of the few avenues through which Black entrepreneurs could access capital, build wealth, and employ community members during a period of severe disinvestment in urban neighborhoods. On the other hand, the very presence of these franchises often reinforced patterns of nutritional inequality, as fast-food outlets proliferated in communities that lacked grocery stores and fresh-food markets. Chatelain contends that evaluating this history requires holding both realities simultaneously rather than reducing the narrative to either celebration or condemnation.', $lyceon_json$[{"key":"A","text":"Fast-food franchises were the primary driver of economic recovery in Black urban neighborhoods during the 1970s, far outweighing the negative health consequences they introduced."},{"key":"B","text":"Chatelain's research reveals that fast-food companies deliberately targeted Black communities as part of a strategy to maximize profits in underserved markets."},{"key":"C","text":"The role of fast-food franchises in Black communities during the 1970s was complex, simultaneously offering economic opportunity and deepening nutritional disparities."},{"key":"D","text":"Historians have generally failed to recognize that franchise ownership was an important path to wealth building for Black entrepreneurs in the twentieth century."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes a paradox: fast-food franchises provided economic opportunity for Black entrepreneurs while reinforcing nutritional inequality, and Chatelain insists both realities must be acknowledged. The option about a complex dual role accurately captures this. The option calling franchises the primary driver of economic recovery overstates the passage, which says they were one of few avenues, not the primary one, and does not claim they outweighed health consequences. The option about deliberate targeting for profit maximization introduces a motive the passage never attributes to the companies. The option about historians generally failing to recognize franchise ownership as important goes beyond the text, which presents Chatelain''s argument without characterizing a broader historiographic failure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22CKVCE', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly support Pollock''s argument as presented in the text?', E'Art historian Griselda Pollock has argued that the absence of women artists from major museum collections is not simply a reflection of historical talent gaps but rather the result of institutional gatekeeping that systematically excluded women from training, exhibitions, and critical recognition. Pollock points out that women such as Artemisia Gentileschi, Judith Leyster, and Edmonia Lewis produced work that rivaled their male contemporaries in technical skill and thematic ambition, yet their paintings were frequently misattributed, undervalued, or left out of canonical art-history surveys.', $lyceon_json$[{"key":"A","text":"A survey of nineteenth-century art academies reveals that the majority formally prohibited women from enrolling in life-drawing classes considered essential for professional advancement."},{"key":"B","text":"Modern auction records indicate that paintings by male Old Masters command significantly higher average prices than paintings by their female contemporaries."},{"key":"C","text":"Recent art-historical scholarship has identified several previously unknown women painters who worked in seventeenth-century Italy and the Dutch Republic."},{"key":"D","text":"Museum visitors in a recent poll expressed strong interest in seeing more exhibitions devoted to underrepresented artists from historically marginalized communities."}]$lyceon_json$::jsonb, 'A', NULL, E'Pollock''s argument is that institutional gatekeeping systematically excluded women from training, exhibitions, and recognition. Evidence that art academies formally barred women from essential classes directly supports the claim of institutional exclusion from training. The finding about auction price differences documents an outcome (lower prices) but does not demonstrate the institutional gatekeeping mechanisms Pollock identifies as the cause. The discovery of previously unknown women painters shows women were active but does not address the institutional barriers Pollock describes. Museum visitors expressing interest in underrepresented artists reflects contemporary attitudes, not historical institutional practices.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW246G4BK', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, what is the most likely point of disagreement between the two authors?', E'Text 1: Ecologist Stuart Pimm contends that the most effective strategy for preserving biodiversity is to protect large, contiguous tracts of habitat. Fragmenting conservation efforts across many small reserves, Pimm argues, leaves species vulnerable to edge effects, genetic isolation, and stochastic population collapse. He points to the success of expansive protected areas in the Amazon basin as evidence that scale is the decisive factor in conservation outcomes.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24KXE0R', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Paleontologist Jack Horner revolutionized the study of dinosaur behavior in the 1970s by excavating nesting sites in Montana. <u>His team uncovered clusters of fossilized eggs arranged in deliberate patterns, with remains of hatchlings nearby.</u> This physical evidence suggested that certain dinosaur species cared for their young, a concept that contradicted the then-dominant view of dinosaurs as indifferent reptilian parents.', $lyceon_json$[{"key":"A","text":"It provides the specific findings that support a broader claim made later in the text."},{"key":"B","text":"It challenges an assumption introduced earlier in the text about excavation methods."},{"key":"C","text":"It summarizes the overall argument of the passage in condensed form."},{"key":"D","text":"It introduces a counterexample that undermines the researcher's original hypothesis about dinosaur nesting behavior."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes what the team found (egg clusters and hatchling remains), and the following sentence uses that evidence to support the claim that dinosaurs cared for their young. Thus the underlined sentence provides specific findings supporting a broader claim. The option about challenging an assumption about excavation methods is wrong because the passage makes no claim about excavation methods that could be challenged. The option about summarizing the overall argument is wrong because the underlined sentence presents only one piece of evidence rather than condensing the entire argument. The option about introducing a counterexample is wrong because the findings support rather than undermine Horner''s hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26VPAH1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Economist Claudia Goldin''s research on the gender pay gap has shown that much of the remaining disparity in earnings between men and women does not stem from overt discrimination but from structural features of how certain professions reward time allocation. In fields such as finance and corporate law, workers who are available for unpredictable, extended hours receive disproportionately higher compensation. <u>A pharmacist earning seventy dollars per hour, by contrast, receives essentially the same rate whether working a Tuesday morning shift or a Saturday evening shift.</u> Goldin argues that occupations with this kind of temporal flexibility have largely closed the gender pay gap, while those that penalize schedule unpredictability continue to sustain it.', $lyceon_json$[{"key":"A","text":"It provides a contrasting example that clarifies the distinction central to the researcher's broader argument about pay disparities."},{"key":"B","text":"It offers an exception that undermines the claim made in the preceding sentences about how professions reward time allocation."},{"key":"C","text":"It supplies biographical context about the researcher's career that explains her interest in the topic of pay structures."},{"key":"D","text":"It introduces a secondary line of argument about wage stagnation in the pharmaceutical industry that the passage does not fully develop."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes a pharmacist who earns the same rate regardless of when the shift occurs, which contrasts with the preceding description of finance and law professionals who earn more for unpredictable hours. This contrast illustrates the structural distinction that Goldin''s argument depends on. The option about undermining the preceding claim is wrong because the pharmacist example supports the argument by showing what happens when temporal flexibility exists, rather than contradicting it. The option about biographical context is wrong because the sentence discusses pharmacy wages, not Goldin''s personal career. The option about wage stagnation in the pharmaceutical industry is wrong because the passage uses the pharmacist as an illustration of temporal flexibility, not as the beginning of a discussion about pharmaceutical industry wages.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW276HLUX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Priya Narayanan''s 2023 analysis of sediment cores from Lake Titicaca revealed elevated copper concentrations dating to approximately 1400 CE, which she attributed to pre-Incan smelting activities along the lake''s tributaries. ______ a 2024 study by Rodrigo Estevez-Blanco found similarly elevated copper levels in sediment layers from the same period at sites over 200 kilometers from any known smelting operation, raising the possibility that atmospheric deposition from volcanic activity, rather than localized smelting runoff, accounts for the widespread copper signature.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"However,"},{"key":"C","text":"For instance,"},{"key":"D","text":"In particular,"}]$lyceon_json$::jsonb, 'B', NULL, E'Narayanan attributed elevated copper to pre-Incan smelting along tributaries. Estevez-Blanco''s findings challenge that interpretation by showing similar copper levels far from any smelting site, suggesting volcanic atmospheric deposition as an alternative explanation. This is a contrast between two competing interpretations of the same data pattern, so "However" correctly signals that the second finding complicates or contradicts the first researcher''s explanation. "Similarly" would indicate the second study reinforces Narayanan''s conclusion, but it actually undermines her smelting-runoff explanation by proposing a different cause. "For instance" would indicate the second study is an example supporting Narayanan''s claim, but it instead challenges her attribution. "In particular" would signal a more specific elaboration of Narayanan''s finding, but Estevez-Blanco''s study introduces an alternative hypothesis rather than refining Narayanan''s.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27D8CQK', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, linguists assumed that the click consonants found in several southern African languages were remnants of an ancient proto-language shared by all click-using populations. Recent genetic and computational analyses, however, have complicated this picture. A 2017 study by Henn and colleagues demonstrated that click consonants emerged independently in at least three unrelated language families, suggesting that the sounds arose through parallel evolution rather than common descent. This finding has forced researchers to reconsider not only the history of click languages but also broader assumptions about how rare phonological features spread across populations.', $lyceon_json$[{"key":"A","text":"It traces the development of a research methodology and then evaluates its limitations in applied fieldwork."},{"key":"B","text":"It presents a longstanding assumption, introduces evidence that challenges it, and then describes the broader implications of that challenge."},{"key":"C","text":"It compares two competing theories of language evolution and argues that neither fully accounts for the observed linguistic data."},{"key":"D","text":"It describes a recent discovery, offers several alternative explanations for it, and concludes that none of the explanations is fully satisfactory."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage first states the longstanding assumption (click consonants descended from a shared proto-language), then introduces the 2017 study that challenges this assumption (parallel evolution), and finally discusses the broader implications for understanding phonological features. The option about tracing a research methodology is wrong because the passage focuses on a finding, not on evaluating a methodology''s limitations. The option about comparing two competing theories is wrong because the passage presents one assumption being overturned by new evidence, not two theories in balanced competition. The option about offering several alternative explanations is wrong because the passage presents one specific finding with one explanation (parallel evolution), not multiple unsatisfactory alternatives.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CA0GUQ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In a 2019 study, marine biologists found that certain species of deep-sea jellyfish produce bioluminescent patterns not merely to attract prey but to ______ potential predators. The light displays mimic the warning signals of toxic organisms, causing approaching fish to veer away even though the jellyfish themselves carry no venom.', $lyceon_json$[{"key":"A","text":"nourish"},{"key":"B","text":"deter"},{"key":"C","text":"camouflage themselves among"},{"key":"D","text":"collaborate with nearby"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explains that the light displays mimic warning signals of toxic organisms, causing approaching fish to veer away. This indicates the jellyfish use bioluminescence to drive away or "deter" predators. "Nourish" means to feed, which has no connection to the described defensive behavior. "Camouflage themselves among" is wrong because the jellyfish are producing conspicuous light displays rather than blending in, and the passage describes mimicry of warning signals, not concealment. "Collaborate with nearby" implies cooperation with predators, which contradicts the passage''s description of predators being driven away.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CN2ZUF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Quantum computing researchers have long debated whether superconducting circuits or trapped-ion systems will prove more practical for large-scale processors. A 2024 study by physicists at the Delft University of Technology found that neither architecture, when tested under identical error-correction protocols, ______ the fault-tolerance threshold that theorists had predicted for systems operating at millikelvin temperatures.', $lyceon_json$[{"key":"A","text":"were able to surpass"},{"key":"B","text":"have been able to surpass"},{"key":"C","text":"was able to surpass"},{"key":"D","text":"are able to surpass"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the verb is "neither architecture," which is grammatically singular. The correlative pronoun "neither" takes a singular verb. Additionally, the sentence reports the finding of a 2024 study using the past tense "found," so the reported-speech clause should use a past-tense verb. "was able to surpass" is both singular (agreeing with "neither architecture") and past tense (consistent with "found"). "were able to surpass" is plural and does not agree with the singular "neither architecture." "have been able to surpass" is plural and in the present perfect, violating both number agreement and tense consistency. "are able to surpass" is plural and in the present tense, again failing to agree in number and shifting away from the past-tense frame established by "found."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GSHF3I', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to explain why the violet-crowned hummingbird nests in sycamore trees. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GXICBI', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support Simard''s hypothesis as described in the text?', E'Ecologist Suzanne Simard has proposed that trees in a forest communicate and share resources through underground fungal networks, sometimes called the "wood wide web." Simard''s hypothesis suggests that older, established trees, which she terms "mother trees," transfer carbon and nutrients to younger seedlings through these mycorrhizal connections, particularly when the seedlings are growing in shaded conditions with limited access to sunlight.', $lyceon_json$[{"key":"A","text":"Seedlings growing in heavily shaded areas near established trees show higher concentrations of carbon isotopes traceable to those older trees than do seedlings growing in open clearings."},{"key":"B","text":"Forests with greater tree species diversity tend to have more extensive fungal networks in their soil than forests dominated by a single tree species."},{"key":"C","text":"Older trees in temperate forests produce significantly more seeds per year than younger trees of the same species growing in comparable conditions."},{"key":"D","text":"Mycorrhizal fungi are found in the root systems of nearly all terrestrial plant species, including both trees and herbaceous ground-cover plants."}]$lyceon_json$::jsonb, 'A', NULL, E'Simard''s hypothesis claims older trees transfer carbon to shaded seedlings through fungal networks. Finding traceable carbon isotopes from older trees in nearby shaded seedlings at higher concentrations than in open-clearing seedlings would directly support this transfer claim. The finding about species diversity and fungal network extent addresses a different question and does not demonstrate resource transfer between trees. The finding about older trees producing more seeds concerns reproduction, not nutrient sharing. The finding about mycorrhizal fungi being widespread confirms fungal presence but does not demonstrate that resources are transferred through those networks.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H2RARU', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to present the biological mechanism that enables tardigrade survival in extreme conditions. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J04AI8', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'The architect Zaha Hadid was known for designs that defied conventional geometry. While critics sometimes dismissed her swooping, fluid structures as impractical, her completed buildings consistently demonstrated that her vision was ______ : each project met rigorous engineering standards while achieving forms that had previously existed only in digital renderings.', $lyceon_json$[{"key":"A","text":"feasible"},{"key":"B","text":"conventional"},{"key":"C","text":"hypothetical"},{"key":"D","text":"funded by international donors"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts critics who called Hadid''s designs impractical with evidence that her completed buildings met engineering standards. This indicates her vision was achievable, or "feasible." "Conventional" contradicts the passage''s description of her work as defying conventional geometry. "Hypothetical" means theoretical or unproven, which is the opposite of what the completed buildings demonstrate. "Funded by international donors" introduces a financial claim entirely unsupported by the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KRAW8S', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'When glass frogs sleep during the day, they become remarkably transparent. A 2022 study published in Science found that these frogs achieve this transparency by pulling nearly 89 percent of their red blood cells out of circulation and packing them into their liver. The liver, shielded by a reflective membrane, conceals the dense cluster of cells from view. When the frogs wake at night, the blood cells re-enter circulation, and the frogs regain their normal, opaque reddish appearance.', $lyceon_json$[{"key":"A","text":"The transparency of glass frogs during sleep likely serves as a form of camouflage that helps them avoid predators active during daylight hours."},{"key":"B","text":"Glass frogs are among the only vertebrates capable of surviving for extended periods with virtually no circulating red blood cells."},{"key":"C","text":"The reflective membrane surrounding the liver of glass frogs is structurally identical to membranes found in other transparent amphibian species."},{"key":"D","text":"Researchers first observed the transparency of glass frogs several decades before they identified the specific physiological mechanism responsible for it."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that frogs become transparent specifically during sleep (daytime), when they would be vulnerable to visual predators, making the inference about camouflage against daytime predators the most logically supported conclusion. The option about surviving with virtually no circulating red blood cells overstates the passage, which does not address whether this is unique among vertebrates. The option about the reflective membrane being structurally identical to those in other species introduces a comparison the passage never makes. The option about researchers observing transparency decades before identifying the mechanism is unsupported by any information in the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KTLMT4', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how does the explanation offered in Text 2 relate to the findings described in Text 1?', E'Text 1: In a 2021 experiment, neuroscientists at the University of Geneva measured the brain activity of 37 participants while they made charitable donation decisions. The researchers found that participants who had been sleep-deprived for 24 hours donated, on average, 41 percent less to charitable causes than participants who had slept normally. Brain imaging showed reduced activity in the temporoparietal junction, a region associated with empathy and social cognition, during the sleep-deprived condition.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LIMTEM', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Historian David Lowenthal has argued that nostalgia distorts our understanding of the past by casting it in an unrealistically favorable light. According to Lowenthal, people who idealize earlier eras ignore the hardships and injustices that characterized those periods, resulting in a sanitized version of history that serves emotional comfort rather than factual accuracy.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MDYHBI', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly weaken the conclusion that resting-state neural connectivity predicts language-learning outcomes independently of other factors?', E'Neuroscientist Chantel Prat has investigated individual differences in language-learning aptitude among adults. Prat''s research team measured resting-state brain activity using electroencephalography (EEG) before participants began an eight-week intensive French course. They found that certain patterns of neural oscillation, particularly the strength of beta and gamma wave connectivity in the right hemisphere, predicted how quickly and accurately participants would acquire the new language. Participants whose resting-state scans showed stronger right-hemisphere connectivity completed the course with significantly higher proficiency scores than those whose scans showed weaker connectivity, even after controlling for factors such as prior language experience, motivation, and hours of study.', $lyceon_json$[{"key":"A","text":"Participants with stronger right-hemisphere connectivity were also found to have significantly higher working-memory capacity, and working memory has been independently shown to be a strong predictor of language-learning success."},{"key":"B","text":"A follow-up study using a different language found that beta and gamma connectivity patterns predicted learning outcomes for Mandarin Chinese as well as for French."},{"key":"C","text":"The EEG equipment used in the study was later found to measure neural oscillations with a margin of error consistent with industry-standard clinical devices."},{"key":"D","text":"Several participants who showed weaker right-hemisphere connectivity reported that they had previously struggled to learn a second language during high school coursework."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage claims neural connectivity predicts language learning even after controlling for other factors. If stronger connectivity correlates with higher working-memory capacity, and working memory independently predicts language success, then the connectivity measure may be a proxy for working memory rather than an independent predictor, directly undermining the conclusion. The finding that the pattern extends to Mandarin strengthens rather than weakens the conclusion by showing it generalizes. The finding about EEG measurement accuracy being industry-standard does not challenge the study''s conclusions about the predictive relationship. The finding that weaker-connectivity participants previously struggled with languages is consistent with the study''s claims rather than challenging them, since it merely confirms the correlation without introducing a confounding variable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NHNW8E', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Restoration ecologist Miriam Vasquez-Torres has documented that the reintroduction of gray wolves to Yellowstone National Park in 1995 reduced elk overgrazing along riverbanks. ______ beaver populations, which depend on streamside willow growth, increased by nearly 900 percent in the two decades following the wolves'' return.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"As a result,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence establishes that wolves reduced elk overgrazing along riverbanks. The second sentence describes beaver populations increasing because streamside willows could recover. This is a cause-and-effect relationship: reduced overgrazing led to willow recovery, which led to beaver population growth. "As a result" correctly signals this causal chain. "In other words" signals a restatement, but the second sentence introduces new information about beavers rather than restating the point about overgrazing. "Nevertheless" signals a contrast or concession, but the beaver increase is consistent with, not contrary to, reduced overgrazing. "On the other hand" signals an opposing perspective, but the beaver recovery supports rather than opposes the finding about reduced overgrazing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O2O16V', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, conservationist Eleanora Whitford proposed relocating a colony of endangered tortoises to a protected atoll in the South ______ initially skeptical, the regional wildlife board eventually approved the plan after reviewing three years of habitat suitability data.', $lyceon_json$[{"key":"A","text":"Pacific, though"},{"key":"B","text":"Pacific; and though"},{"key":"C","text":"Pacific and though"},{"key":"D","text":"Pacific; though"}]$lyceon_json$::jsonb, 'D', NULL, E'The text contains two independent clauses: the first ends at "Pacific" and the second begins with "though initially skeptical, the regional wildlife board eventually approved the plan." A semicolon correctly joins two independent clauses without a coordinating conjunction. Using a comma alone ("Pacific, though") creates a comma splice, since both clauses are independent. Using a semicolon followed by a coordinating conjunction ("Pacific; and though") is redundant and non-standard: a semicolon already performs the function of the conjunction. Omitting the comma before the coordinating conjunction ("Pacific and though") violates the convention that a comma must precede a coordinating conjunction joining two independent clauses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PS327A', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the relationship between a language''s social context and its structural complexity?', E'Linguist John McWhorter has observed that languages tend to become structurally simpler when they are widely learned by adult non-native speakers. Old English, for instance, had elaborate case endings, grammatical gender, and verb conjugations that largely disappeared after sustained contact with Norse-speaking settlers in medieval England. McWhorter notes, however, that languages spoken in small, isolated communities often retain or even develop greater morphological complexity over time. Tuyuca, spoken by roughly 1,500 people in the Amazon basin, requires speakers to mark on every verb whether the information conveyed was witnessed firsthand, inferred from evidence, or reported by another person.', $lyceon_json$[{"key":"A","text":"Languages that undergo significant contact with speakers of other languages tend to shed grammatical complexity, while those used primarily among native speakers in smaller communities tend to preserve or increase it."},{"key":"B","text":"The grammatical complexity of a language is determined almost entirely by the size of the community that speaks it, with smaller communities inevitably producing more complex grammars."},{"key":"C","text":"Old English lost its structural complexity primarily because Norse was a grammatically simpler language whose patterns displaced the more complex English forms through direct borrowing."},{"key":"D","text":"Evidentiality markers like those found in Tuyuca are a feature of all languages spoken in isolated communities, reflecting universal cognitive tendencies among small populations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two patterns: contact with non-native speakers leads to simplification (Old English losing complexity after Norse contact), while isolation preserves or increases complexity (Tuyuca). The option describing this dual relationship is the most supported inference. The option claiming complexity is determined almost entirely by community size overstates the argument by making it absolute and ignoring the role of language contact. The option about Norse being grammatically simpler and displacing English forms through borrowing misrepresents the passage, which attributes simplification to adult non-native speakers learning the language, not to direct borrowing from a simpler language. The option claiming evidentiality markers are universal in isolated communities extrapolates from one example to all such languages, which the passage does not support.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RAKFZV', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to emphasize the design feature that makes the Aranya project adaptable for its residents. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SXEWC0', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best describes the main idea of the text?', E'Researchers at the University of Oulu in Finland recently examined how reindeer adapt to the extreme light conditions of the Arctic. During winter, reindeer eyes shift from gold to deep blue, a transformation that increases their sensitivity to ultraviolet light. This adaptation allows them to detect predators and forage for lichen even during the prolonged polar darkness, when visible light is nearly absent. The change reverses in summer, when the eyes return to gold to handle the intense, continuous daylight.', $lyceon_json$[{"key":"A","text":"Reindeer eyes undergo a seasonal color change that helps them survive the extreme light conditions of the Arctic."},{"key":"B","text":"The polar darkness of Arctic winters creates conditions in which most large mammals struggle to find adequate food."},{"key":"C","text":"Finnish researchers have recently discovered that reindeer can perceive ultraviolet wavelengths of light throughout the entire year."},{"key":"D","text":"The gold coloring of reindeer eyes during summer months protects their retinas from damage caused by continuous sunlight exposure."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how reindeer eyes change color seasonally to cope with Arctic light extremes, making the option about a seasonal color change aiding survival the best summary of the main idea. The option about most large mammals struggling to find food in polar darkness goes beyond the passage, which discusses only reindeer. The option claiming reindeer perceive ultraviolet light year-round misreads the text, which states the UV sensitivity is a winter adaptation. The option about gold coloring protecting retinas from damage adds a claim not stated in the passage, which merely says the eyes return to gold in summer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TMGGZ5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every spring, the coastal village of Bryndwr hosts a festival celebrating regional folk music. Each of the seventeen ensembles that performed at last year''s ______ a unique arrangement of a traditional Welsh hymn, drawing on harmonies passed down through multiple generations of local choristers.', $lyceon_json$[{"key":"A","text":"festival have presented"},{"key":"B","text":"festival presenting"},{"key":"C","text":"festival presented"},{"key":"D","text":"festival, presenting"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the clause is "Each," which is singular and requires a singular verb. The sentence describes a completed past event ("last year''s festival"), so the simple past tense "presented" is correct. "have presented" uses a plural verb form ("have") that does not agree with the singular subject "Each." "festival presenting" omits the main verb entirely, turning the sentence into a fragment with no finite verb. "festival, presenting" also lacks a finite verb; the comma followed by a present participle creates a participial phrase rather than a main clause, leaving the sentence incomplete.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V8Q9CH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Glaciologist Marta Sevilla has spent over a decade studying the retreat of Andean glaciers. Her recent fieldwork in the Cordillera Blanca ______ that several ice formations previously considered stable have thinned by nearly forty percent since 2011.', $lyceon_json$[{"key":"A","text":"confirms, that"},{"key":"B","text":"confirms"},{"key":"C","text":"confirms;"},{"key":"D","text":"confirms. That"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence requires a verb ("confirms") followed directly by a noun clause beginning with "that." No punctuation should separate a verb from its noun-clause complement. Inserting a comma before "that" ("confirms, that") incorrectly interrupts the verb-complement connection. A semicolon after "confirms" would require an independent clause to follow, but "that several ice formations..." is a dependent clause. Placing a period after "confirms" and capitalizing "That" creates a sentence fragment beginning with a subordinating conjunction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VJVD61', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'In 2019, marine biologist Ayana Elizabeth Johnson proposed that coral reef conservation could be more effective if local fishing communities were treated as partners rather than obstacles. Traditional conservation approaches often restrict fishing outright, which can devastate the livelihoods of coastal populations and breed resentment that undermines enforcement. Johnson''s model, tested in Curaçao, involved mapping reef zones collaboratively with fishers, designating some areas as no-take reserves while keeping others open under agreed-upon catch limits. Preliminary data from the pilot showed that fish biomass in the protected zones increased by 171 percent over three years, while fishers in the open zones reported stable or improved catches.', $lyceon_json$[{"key":"A","text":"Johnson's research demonstrates that coral reef ecosystems recover fastest when all commercial fishing activity in surrounding waters is permanently halted."},{"key":"B","text":"Collaborative conservation models that include local fishers as partners can produce significant ecological gains while preserving fishing livelihoods."},{"key":"C","text":"The economy of Curaçao depends heavily on small-scale fishing, making it an ideal location for marine conservation experiments."},{"key":"D","text":"Preliminary data from reef studies generally indicate that fish biomass increases whenever no-take reserves are established in tropical waters."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on Johnson''s collaborative approach to reef conservation, showing it yielded ecological benefits (171% biomass increase) without harming fishing livelihoods, so the option about collaborative models producing ecological gains while preserving livelihoods captures the main idea. The option claiming reef ecosystems recover fastest when all fishing is halted contradicts the passage, which explicitly argues against blanket fishing restrictions. The option about Curaçao''s economic dependence on fishing introduces a claim not made in the text. The option generalizing that fish biomass increases whenever no-take reserves are established overstates the passage, which presents results from one pilot study only.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XP6KDK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The muralist Davi Kopenawa Nascimento draws on Yanomami cosmological narratives to create large-scale public ______ his 2019 installation in Manaus, for example, depicted the sky spirit Omama using pigments derived entirely from Amazonian clay and crushed minerals.', $lyceon_json$[{"key":"A","text":"works and, his"},{"key":"B","text":"works his"},{"key":"C","text":"works; his"},{"key":"D","text":"works, his"}]$lyceon_json$::jsonb, 'C', NULL, E'Two independent clauses appear here: the first describes what Nascimento does generally, and the second provides a specific example. A semicolon correctly joins the two independent clauses. Using no punctuation ("works his") creates a run-on sentence. Using only a comma ("works, his") creates a comma splice, joining two independent clauses with only a comma and no coordinating conjunction. Placing the comma after rather than before the conjunction ("works and, his") mispositions the punctuation: in Standard English, a comma precedes a coordinating conjunction joining independent clauses, not follows it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YJA8NG', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Tashkent Institute of Seismology have developed a network of underground sensors that can detect tectonic stress changes weeks before an earthquake ______ the sensors, which rely on piezoelectric crystals embedded in boreholes drilled to depths of ninety meters, have already provided early warnings for two moderate tremors in the Fergana Valley.', $lyceon_json$[{"key":"A","text":"occurs. The sensors, which"},{"key":"B","text":"occurs; the sensors which"},{"key":"C","text":"occurs, the sensors, which"},{"key":"D","text":"occurs. The sensors which"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses must be separated here: the first describes what the sensor network can detect, and the second describes what the sensors have already accomplished. A period correctly separates them. The phrase "which rely on piezoelectric crystals embedded in boreholes drilled to depths of ninety meters" is a nonrestrictive relative clause modifying "sensors" and must be set off by commas on both sides. "occurs. The sensors, which" provides both the correct sentence boundary (period) and the correct punctuation for the nonrestrictive clause (commas). "occurs; the sensors which" uses a semicolon to join the clauses but drops the comma before "which," turning the nonrestrictive clause into a restrictive one and implying there are other sensors that do not rely on piezoelectric crystals. "occurs, the sensors, which" creates a comma splice between the two independent clauses. "occurs. The sensors which" correctly uses a period but omits the comma before "which," again incorrectly making the clause restrictive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z4WLV6', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'During the 1830s, the geologist Mary Anning made a series of remarkable fossil discoveries along the Dorset coast. Her finds were so significant that they ______ the prevailing scientific understanding of prehistoric life, prompting researchers across Europe to reconsider long-held assumptions about extinction.', $lyceon_json$[{"key":"A","text":"funded"},{"key":"B","text":"transformed"},{"key":"C","text":"overlooked"},{"key":"D","text":"verified the accuracy of"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that Anning''s finds prompted researchers to reconsider long-held assumptions, indicating the discoveries changed scientific understanding. "Transformed" captures this meaning of fundamentally altering. "Funded" is wrong because the passage discusses intellectual impact, not financial support. "Overlooked" produces the opposite meaning, suggesting the finds were ignored, which contradicts the passage. "Verified the accuracy of" implies the existing understanding was confirmed, which contradicts the statement that assumptions were reconsidered.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZZB5XW', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, which choice most logically completes the text?', E'Economist Lisa Cook has documented how episodes of racial violence in the early twentieth-century United States corresponded with sharp declines in patent filings by Black inventors. Cook analyzed patent records from 1870 to 1940 and cross-referenced them with documented lynchings, race riots, and the enactment of segregation laws. She found that African American patenting activity dropped measurably in the years immediately following major violent episodes, even in states geographically distant from the events themselves. White patenting rates showed no comparable decline during the same periods.', $lyceon_json$[{"key":"A","text":"The chilling effect of racial violence on Black innovation extended beyond the immediate geographic area of the violence, suggesting that the threat of violence inhibited inventive activity broadly across the Black population."},{"key":"B","text":"Cook's findings demonstrate that racial violence was the sole factor responsible for the persistent gap in patenting rates between Black and white inventors throughout the twentieth century."},{"key":"C","text":"Patent filings are an unreliable measure of innovation because many inventors, particularly those facing discrimination, chose to pursue inventions without seeking formal patent protection."},{"key":"D","text":"White inventors were largely unaware of the episodes of racial violence documented in Cook's study, which explains why their patenting rates remained unaffected during those periods."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explicitly states that patenting declines occurred even in states distant from the violence, directly supporting the inference that the chilling effect extended geographically beyond the immediate area. The option claiming violence was the sole factor responsible for the entire patenting gap overstates the findings, which document a correlation during specific episodes rather than attributing the entire gap to one cause. The option arguing patent filings are unreliable measures of innovation introduces a methodological critique not raised or implied in the text. The option suggesting white inventors were unaware of the violence fabricates an explanation the passage does not offer for why white rates were unaffected.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
